import type { Config } from '../config/config.js';

/**
 * Prefix used to demarcate just-in-time discovered project context that is
 * appended to a tool's LLM-facing content.
 */
export const JIT_CONTEXT_PREFIX =
  '\n\n--- Newly Discovered Project Context ---\n';

/**
 * Suffix used to demarcate just-in-time discovered project context that is
 * appended to a tool's LLM-facing content.
 */
export const JIT_CONTEXT_SUFFIX = '\n--- End Project Context ---';

/**
 * Discovers just-in-time (JIT) project context for a given accessed path.
 *
 * Returns an empty string if JIT context is disabled, no context manager is
 * available, nothing is discovered, or an error occurs during discovery.
 */
export async function discoverJitContext(
  config: Config,
  accessedPath: string,
): Promise<string> {
  if (!config.isJitContextEnabled()) {
    return '';
  }

  const contextManager = config.getContextManager();
  if (!contextManager) {
    return '';
  }

  try {
    const workspaceDirectories = [
      ...config.getWorkspaceContext().getDirectories(),
    ];
    return await contextManager.discoverContext(
      accessedPath,
      workspaceDirectories,
    );
  } catch {
    return '';
  }
}

/**
 * Appends discovered JIT context to the given LLM content. If the JIT context
 * is empty, the original content is returned unchanged.
 */
export function appendJitContext(
  llmContent: string,
  jitContext: string,
): string {
  if (!jitContext) {
    return llmContent;
  }
  return `${llmContent}${JIT_CONTEXT_PREFIX}${jitContext}${JIT_CONTEXT_SUFFIX}`;
}
